def numTeams(rating):
    res, n = 0, len(rating)
    for i in range(1, n - 1):
        ll = lg = rl = rg = 0
        for j in range(i):
            if rating[j] < rating[i]: ll += 1
            else: lg += 1
        for j in range(i + 1, n):
            if rating[j] < rating[i]: rl += 1
            else: rg += 1
        res += ll * rg + lg * rl
    return res

